#include <algorithm>
#include <cassert>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>
using namespace std;
// a와 b는 서로 다른 비어 있지 않은 문자열에 대응합니다. 빠진 기호에는 값을 정하지 않습니다.
bool matches(const string&pattern,const string&text){
 for(char c:pattern)if(c!='a'&&c!='b')throw invalid_argument("pattern");
 if(pattern.empty())return text.empty();
 size_t ca=count(pattern.begin(),pattern.end(),'a'),cb=pattern.size()-ca;
 if(ca==0||cb==0){
  if(text.empty()||text.size()%pattern.size()!=0)return false;
  size_t length=text.size()/pattern.size();string unit=text.substr(0,length);
  for(size_t i=0;i<text.size();i+=length)if(text.compare(i,length,unit)!=0)return false;
  return true;
 }
 for(size_t la=1;la<=text.size()/ca;++la){
  size_t remaining=text.size()-ca*la;
  if(remaining==0||remaining%cb!=0)continue;
  size_t lb=remaining/cb,pos=0;string a,b;bool seenA=false,seenB=false,ok=true;
  for(char c:pattern){size_t len=c=='a'?la:lb;string part=text.substr(pos,len);pos+=len;
   string& value=c=='a'?a:b;bool& seen=c=='a'?seenA:seenB;
   if(!seen){value=part;seen=true;}else if(value!=part){ok=false;break;}
  }
  if(ok&&a!=b)return true;
 }
 return false;
}
bool matchReference(const string&p,const string&t){
 if(p.empty())return t.empty();
 vector<string>words;
 for(size_t i=0;i<t.size();++i)for(size_t len=1;i+len<=t.size();++len)words.push_back(t.substr(i,len));
 sort(words.begin(),words.end());words.erase(unique(words.begin(),words.end()),words.end());
 bool hasA=p.find('a')!=string::npos,hasB=p.find('b')!=string::npos;
 for(const string&a:words)for(const string&b:words){
  if(hasA&&hasB&&a==b)continue;
  string expanded;for(char c:p)expanded+=(c=='a'?a:b);
  if(expanded==t)return true;
 }
 return false;
}
vector<string> strings(const string&alphabet,int maximum){
 vector<string>all(1,""),level(1,"");for(int n=1;n<=maximum;++n){vector<string>next;for(const string&s:level)for(char c:alphabet)next.push_back(s+c);all.insert(all.end(),next.begin(),next.end());level=next;}return all;
}
int main(){size_t cases=0;for(const string&p:strings("ab",5))for(const string&t:strings("xy",6)){assert(matches(p,t)==matchReference(p,t));++cases;}assert(!matches("ab","xx"));assert(matches("a","xx"));bool bad=false;try{matches("c","x");}catch(const invalid_argument&){bad=true;}assert(bad);assert(matches(string(1000,'a'),string(1000,'x')));assert(!matches(string(999,'a')+"b",string(1000,'x')));cout<<cases<<" cases\n";}
